(function(root){'use strict';
class PartyDialog{
 constructor(options){this.options=options;this.people=null;this.key='';this.saving=false;this.error='';}
 open(){
  this.people=null;this.key='';this.error='';
  this.options.openDialog('Party Recommendations',`<form id="partySearchForm"><label for="partyPeople">How many people?</label><div class="party-search-input"><input id="partyPeople" type="number" inputmode="numeric" min="1" max="120" step="1" value="10" required><button type="submit" class="primary">FIND TABLES</button></div></form><div id="partyResults" aria-live="polite"><p class="helper">Find READY tables in active sections and additional options outside the active formation.</p></div>`);
  document.getElementById('partySearchForm').onsubmit=e=>{e.preventDefault();if(this.saving)return;this.error='';this.people=Number(document.getElementById('partyPeople').value);this.crossSection=root.PartyRecommendations.canCrossSections(this.people);this.key='';this.refresh();};
  document.getElementById('partyPeople').oninput=()=>{this.people=null;document.getElementById('partyResults').innerHTML='<p class="helper">Press FIND TABLES to update recommendations.</p>';};
  document.getElementById('partyPeople').focus();document.getElementById('partyPeople').select();
 }
 refresh(){
  const target=document.getElementById('partyResults');if(!target||!document.getElementById('modal').open||this.people===null||this.saving)return;
  const o=this.options,context=o.context(),esc=o.escape;
  const report=context.live?root.PartyRecommendations.search({...context,people:this.people,allowCrossSection:this.crossSection}):{candidates:[],reason:'Wait until LIVE to check current table availability.',crossSectionCount:0};
  const key=JSON.stringify([report,this.people,context.shift,context.formationLabel,context.state?.revision,JSON.stringify(context.config?.formations),this.crossSection,this.error]);if(this.key===key)return;this.key=key;
  const cards=report.candidates.map((c,i)=>{const heading=c.inactive&&(i===0||!report.candidates[i-1].inactive)?'<h3 class="party-group-heading">OTHER SECTION / FORMATION</h3><p class="helper">Additional READY options. Choose an active server before accepting.</p>':i===0?'<h3 class="party-group-heading">ACTIVE SECTION OPTIONS</h3>':'';return heading+(c.inactive?PartyDialog.backupCard(c,i,this.people,esc):`<article class="party-option ${i===0?'party-best':''}" data-party-tables="${esc(c.tables.join('|'))}"><div class="party-option-heading"><span>${i===0?'TOP MATCH':'OPTION '+(i+1)}</span><strong>${esc(c.tables.join(' + '))}</strong><b>${c.min===c.max?c.max:c.min+'–'+c.max} seats</b><span class="party-seating-type">${esc(c.seatingType)}</span></div><p class="party-server">${esc(c.server)} · <b>BEEPER ${esc(c.beeper)}</b></p>${c.returnPriority?`<p class="party-return"><strong>RETURN TURN</strong> · ${c.returnReason==='recovery'?'10-minute recovery complete.':'A fitting table is READY again.'}</p>`:''}<p>Section ${esc(c.section)} · Rotation #${c.rotation} · ${c.turns} turns</p><div class="party-load"><span><b>${c.activeGuests}</b> guests now</span><span><b>${c.activeTables}</b> tables now</span><span><b>${c.afterGuests}</b> guests after</span></div>${c.recentParties?`<p class="party-caution">Seated ${c.recentGuests} guests in the last 5 minutes.</p>`:''}${c.crossSection?`<p class="party-caution"><strong>CROSS-SECTION · Coordinate before seating.</strong><br>${esc(c.servers.map(s=>s.name+' (Section '+s.section+', Beeper '+s.beeper+')').join(' + '))}<br>Suggested lead: ${esc(c.server)}. ACCEPT assigns the entire party to this lead server.</p>`:''}<button type="button" class="primary party-accept" data-party-accept="${i}" aria-label="Accept ${esc(c.tables.join(' plus '))}, ${this.people} guests, ${esc(c.server)}">ACCEPT</button></article>`);}).join('');
  target.innerHTML=`<div class="party-results-header"><h3>${this.people} guests · ${esc(context.shift)} · ${esc(context.formationLabel||'No formation')}</h3><button id="partyRefresh" type="button">REFRESH</button></div><p class="helper">${report.backupCount?'Active matches are listed first, followed by other READY section / formation options. ':''}${report.candidates.length} option${report.candidates.length===1?'':'s'} · Eligible return turns first. ${this.people<5?'1–4 guests: follow Board rotation, then a fitting READY booth before a regular table.':'5+ guests: nearest turn count, then L/R → C → A/B → E → H/M and server workload.'} ${this.people>12?'13+ guests: approved cross-section combinations are included; same-section options come first.':'Up to 12 guests: keep all tables in one section.'}</p>${this.error?`<p class="party-error" role="alert">${esc(this.error)}</p>`:''}${report.recovering?.length?`<p class="party-caution">TURN HELD · ${esc(report.recovering.map(r=>r.server+' — '+r.minutes+' min recovery remaining').join('; '))}. Priority returns after 10 minutes from the last seating, when a fitting table is READY.</p>`:''}${cards||`<p class="party-empty">${esc(report.reason)}</p>`}${report.crossSectionCount?`<button id="partyCrossSection" type="button" class="full">${this.crossSection?'HIDE CROSS-SECTION OPTIONS':'SHOW '+report.crossSectionCount+' CROSS-SECTION OPTION'+(report.crossSectionCount===1?'':'S')}</button>`:''}<p class="helper">ACCEPT seats this party on the listed table(s), records it on Board and updates Floor. Previously passed servers regain first priority when eligible. Review the server and current workload before accepting.</p>`;
  document.getElementById('partyRefresh').onclick=()=>{this.key='';this.refresh();};
  target.querySelectorAll('[data-party-server]').forEach(select=>select.onchange=()=>{target.querySelector('[data-party-accept="'+select.dataset.partyServer+'"]').disabled=!select.value;});
  target.querySelectorAll('[data-party-accept]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.partyAccept),c=report.candidates[i];return this.accept(c.inactive?{...c,rowId:(target.querySelector('[data-party-server="'+i+'"]')?.value||'')}:c,context);});
  const cross=document.getElementById('partyCrossSection');if(cross)cross.onclick=()=>{this.crossSection=!this.crossSection;this.key='';this.refresh();};
 }
 static backupCard(c,i,people,esc,kind='party'){
  const choices=c.serverChoices||[],chooseAttr=kind==='res'?'data-res-server':'data-party-server',acceptAttr=kind==='res'?'data-res-accept':'data-party-accept';
  return `<article class="party-option party-backup" data-party-tables="${esc(c.tables.join('|'))}"><div class="party-option-heading"><span>BACKUP OPTION</span><strong>${esc(c.tables.join(' + '))}</strong><b>${c.min===c.max?c.max:c.min+'–'+c.max} seats</b><span>${esc(c.seatingType)}</span></div><p><strong>${esc(c.formationLabel)} · Section ${esc(c.section)}</strong>${c.crossSection?' · CROSS-SECTION':''}</p><p class="party-caution">${esc(c.inactiveTables.map(t=>t.table+' · '+t.reason).join('; '))}<br>Coordinate opening these READY tables with the selected server. ACCEPT seats this party with that server; it does not switch the whole shift formation.</p><label for="${kind}BackupServer${i}">Server for this party</label><select class="field" id="${kind}BackupServer${i}" ${chooseAttr}="${i}"><option value="">Choose active server…</option>${choices.map((r,n)=>`<option value="${esc(r.rowId)}">${esc(r.server)} · Beeper ${esc(r.beeper)} · ${r.turns} turns · ${r.activeGuests} guests now${n===0?' · SUGGESTED':''}</option>`).join('')}</select>${choices.length?'':'<p class="party-caution">No eligible active server. Assign or uncut a server, or wait for recovery, then refresh.</p>'}<button type="button" class="primary party-accept" ${acceptAttr}="${i}" disabled>ACCEPT · SEAT BACKUP TABLES</button></article>`;
 }
 async accept(candidate,context){
  if(this.saving||!document.getElementById('modal').open||!document.getElementById('partyResults'))return;
  this.saving=true;this.error='';
  document.getElementById('modalBody').querySelectorAll('button,input').forEach(el=>el.disabled=true);
  try{await this.options.accept(candidate,this.people,context);}catch(error){this.error=error.message||'Seating was not confirmed. Please check the Floor.';}
  finally{this.saving=false;this.key='';document.getElementById('partySearchForm')?.querySelectorAll('button,input').forEach(el=>el.disabled=false);this.refresh();}
 }
}
root.PartyDialog=PartyDialog;
})(globalThis);
